54	static uint32_t ls2k300_spi_setfrequency(FAR struct spi_dev_s *dev,
55	                                         uint32_t frequency)
56	{
57	  FAR struct ls2k300_spi_priv_s *priv =
58	      (FAR struct ls2k300_spi_priv_s *)dev;
59	  uint8_t sper_val;
60	  uint8_t spcr_val;
61	  uint32_t div;
62	
63	  if (frequency == 0)
64	    {
65	      frequency = priv->clock_freq / 2;
66	    }
67	
68	  div = priv->clock_freq / (2 * frequency);
69	  if (div < 1)
70	    {
71	      div = 1;
72	    }
73	
74	  if (div > 256)
75	    {
76	      div = 256;
77	    }
78	
79	  sper_val = 0;
80	  if (div > 1)
81	    {
82	      sper_val = (uint8_t)((div - 1) & 0xff);
83	    }
84	
85	  spi_write_reg(priv, LS2K300_SPI_SPER, sper_val);
86	
87	  spcr_val = spi_read_reg(priv, LS2K300_SPI_SPCR);
88	  spcr_val &= ~0x0c;
89	  if (div > 256)
90	    {
91	      spcr_val |= 0x08;
92	    }
93	
94	  spi_write_reg(priv, LS2K300_SPI_SPCR, spcr_val);
95	
96	  priv->frequency = priv->clock_freq / (2 * div);
97	  return priv->frequency;
98	}
