100	static void ls2k300_spi_setmode(FAR struct spi_dev_s *dev,
101	                                enum spi_mode_e mode)
102	{
103	  FAR struct ls2k300_spi_priv_s *priv =
104	      (FAR struct ls2k300_spi_priv_s *)dev;
105	  uint8_t spcr_val;
106	
107	  spcr_val = spi_read_reg(priv, LS2K300_SPI_SPCR);
108	  spcr_val &= ~0x0c;
109	
110	  switch (mode)
111	    {
112	      case SPIDEV_MODE0:
113	        break;
114	      case SPIDEV_MODE1:
115	        spcr_val |= 0x04;
116	        break;
117	      case SPIDEV_MODE2:
118	        spcr_val |= 0x08;
119	        break;
120	      case SPIDEV_MODE3:
121	        spcr_val |= 0x0c;
122	        break;
123	      default:
124	        return;
125	    }
126	
127	  spi_write_reg(priv, LS2K300_SPI_SPCR, spcr_val);
128	  priv->mode = mode;
129	}
