144	static uint32_t ls2k300_spi_send(FAR struct spi_dev_s *dev, uint32_t wd)
145	{
146	  FAR struct ls2k300_spi_priv_s *priv =
147	      (FAR struct ls2k300_spi_priv_s *)dev;
148	  uint8_t spsr_val;
149	
150	  spi_write_reg(priv, LS2K300_SPI_FIFO, (uint8_t)(wd & 0xff));
151	
152	  do
153	    {
154	      spsr_val = spi_read_reg(priv, LS2K300_SPI_SPSR);
155	    }
156	  while ((spsr_val & SPSR_SPIF) == 0);
157	
158	  spi_read_reg(priv, LS2K300_SPI_SPSR);
159	
160	  return (uint32_t)spi_read_reg(priv, LS2K300_SPI_FIFO);
161	}
