163	#ifdef CONFIG_SPI_EXCHANGE
164	static void ls2k300_spi_exchange(FAR struct spi_dev_s *dev,
165	                                 FAR const void *txbuffer,
166	                                 FAR void *rxbuffer,
167	                                 size_t nwords)
168	{
169	  FAR struct ls2k300_spi_priv_s *priv =
170	      (FAR struct ls2k300_spi_priv_s *)dev;
171	  FAR const uint8_t *txptr = (FAR const uint8_t *)txbuffer;
172	  FAR uint8_t *rxptr = (FAR uint8_t *)rxbuffer;
173	  uint8_t spsr_val;
174	  uint8_t tx_data;
175	  uint8_t rx_data;
176	  size_t i;
177	
178	  for (i = 0; i < nwords; i++)
179	    {
180	      if (txptr)
181	        {
182	          tx_data = *txptr++;
183	        }
184	      else
185	        {
186	          tx_data = 0xff;
187	        }
188	
189	      spi_write_reg(priv, LS2K300_SPI_FIFO, tx_data);
190	
191	      do
192	        {
193	          spsr_val = spi_read_reg(priv, LS2K300_SPI_SPSR);
194	        }
195	      while ((spsr_val & SPSR_SPIF) == 0);
196	
197	      spi_read_reg(priv, LS2K300_SPI_SPSR);
198	
199	      rx_data = spi_read_reg(priv, LS2K300_SPI_FIFO);
200	
201	      if (rxptr)
202	        {
203	          *rxptr++ = rx_data;
204	        }
205	    }
206	}
207	#endif
