261	FAR struct spi_dev_s *ls2k300_spiflash_initialize(int port)
262	{
263	  FAR struct ls2k300_spi_priv_s *priv;
264	  uint8_t spcr_val;
265	
266	  if (port < 0 || port > 1)
267	    {
268	      return NULL;
269	    }
270	
271	  priv = &g_spi_priv[port];
272	
273	  if (!priv->initialized)
274	    {
275	      spi_write_reg(priv, LS2K300_SPI_SPER, 0x07);
276	
277	      spcr_val = SPCR_SPE;
278	      spi_write_reg(priv, LS2K300_SPI_SPCR, spcr_val);
279	
280	      spi_write_reg(priv, LS2K300_SPI_SFCS, 0x00);
281	
282	      priv->initialized = true;
283	    }
284	
285	  return &priv->dev;
286	}
