57	static int spiio_idle_sr1(FAR struct ls2k300_spiio_priv_s *priv,
58	                          uint32_t bit, uint32_t timeout)
59	{
60	  uint32_t sr1;
61	  uint32_t count = 0;
62	
63	  while (count < timeout)
64	    {
65	      sr1 = spiio_read_reg(priv, LS2K300_SPIIO_SR1);
66	      if (sr1 & bit)
67	        {
68	          return 0;
69	        }
70	      count++;
71	    }
72	
73	  return -ETIMEDOUT;
74	}
