132	static void ls2k300_spiio_setmode(FAR struct spi_dev_s *dev,
133	                                  enum spi_mode_e mode)
134	{
135	  FAR struct ls2k300_spiio_priv_s *priv =
136	      (FAR struct ls2k300_spiio_priv_s *)dev;
137	  uint32_t cfg1;
138	
139	  cfg1 = spiio_read_reg(priv, LS2K300_SPIIO_CFG1);
140	  cfg1 &= ~(CFG1_CPOL | CFG1_CPHA);
141	
142	  switch (mode)
143	    {
144	      case SPIDEV_MODE0:
145	        break;
146	      case SPIDEV_MODE1:
147	        cfg1 |= CFG1_CPHA;
148	        break;
149	      case SPIDEV_MODE2:
150	        cfg1 |= CFG1_CPOL;
151	        break;
152	      case SPIDEV_MODE3:
153	        cfg1 |= CFG1_CPOL | CFG1_CPHA;
154	        break;
155	      default:
156	        return;
157	    }
158	
159	  spiio_write_reg(priv, LS2K300_SPIIO_CFG1, cfg1);
160	  priv->mode = mode;
161	}
