163	static void ls2k300_spiio_setbits(FAR struct spi_dev_s *dev, int nbits)
164	{
165	  FAR struct ls2k300_spiio_priv_s *priv =
166	      (FAR struct ls2k300_spiio_priv_s *)dev;
167	  uint32_t cfg1;
168	
169	  if (nbits < 4 || nbits > 32)
170	    {
171	      return;
172	    }
173	
174	  cfg1 = spiio_read_reg(priv, LS2K300_SPIIO_CFG1);
175	  cfg1 &= ~CFG1_DSIZE_MASK;
176	  cfg1 |= ((nbits - 1) << CFG1_DSIZE_SHIFT);
177	  spiio_write_reg(priv, LS2K300_SPIIO_CFG1, cfg1);
178	
179	  priv->nbits = nbits;
180	}
