213	static void ls2k300_spiio_exchange(FAR struct spi_dev_s *dev,
214	                                   FAR const void *txbuffer,
215	                                   FAR void *rxbuffer,
216	                                   size_t nwords)
217	{
218	  FAR struct ls2k300_spiio_priv_s *priv =
219	      (FAR struct ls2k300_spiio_priv_s *)dev;
220	  FAR const uint8_t *txptr = (FAR const uint8_t *)txbuffer;
221	  FAR uint8_t *rxptr = (FAR uint8_t *)rxbuffer;
222	  size_t i;
223	
224	  for (i = 0; i < nwords; i++)
225	    {
226	      if (spiio_idle_sr1(priv, SR1_TXA, SPIIO_TIMEOUT) < 0)
227	        {
228	          break;
229	        }
230	
231	      if (txptr)
232	        {
233	          spiio_write_reg_byte(priv, LS2K300_SPIIO_DR, *txptr++);
234	        }
235	      else
236	        {
237	          spiio_write_reg_byte(priv, LS2K300_SPIIO_DR, 0x00);
238	        }
239	
240	      spiio_write_reg(priv, LS2K300_SPIIO_CR1,
241	                      CR1_SPE | CR1_CSTART | CR1_AUTOSUS);
242	
243	      if (spiio_idle_sr1(priv, SR1_EOT, SPIIO_TIMEOUT) < 0)
244	        {
245	          break;
246	        }
247	
248	      spiio_write_reg(priv, LS2K300_SPIIO_SR1, SR1_EOT);
249	
250	      if (spiio_idle_sr1(priv, SR1_RXA, SPIIO_TIMEOUT) < 0)
251	        {
252	          break;
253	        }
254	
255	      if (rxptr)
256	        {
257	          *rxptr++ = spiio_read_reg_byte(priv, LS2K300_SPIIO_DR);
258	        }
259	      else
260	        {
261	          spiio_read_reg_byte(priv, LS2K300_SPIIO_DR);
262	        }
263	    }
264	}
