52	/****************************************************************************
53	 * Name: gd32_gd25_automount
54	 *
55	 * Description:
56	 *   Initialize, configure, and mount the GD25 SPI FLASH.  The FLASH will
57	 *   be mounted at /dev/gd25.
58	 *
59	 ****************************************************************************/
60	
61	int gd32_gd25_automount(int minor)
62	{
63	  struct spi_dev_s *spi;
64	  struct mtd_dev_s *mtd;
65	  static bool initialized = false;
66	  int ret;
67	
68	  /* Have we already initialized? */
69	
70	  if (!initialized)
71	    {
72	      /* No.. Get the SPI port driver */
73	
74	      spi = gd32_spibus_initialize(SPI_FLASH_CSNUM);
75	      if (!spi)
76	        {
77	          syslog(LOG_ERR, "ERROR: Failed to initialize SPI port %d\n",
78	                 SPI_FLASH_CSNUM);
79	          return -ENODEV;
80	        }
81	
82	      /* Now bind the SPI interface to the GD25 SPI FLASH driver */
83	
84	      mtd = gd25_initialize(spi, 0);
85	      if (!mtd)
86	        {
87	          syslog(LOG_ERR, "ERROR: Failed to bind SPI port to the \
88	                 GD25 FLASH driver\n");
89	          return -ENODEV;
90	        }
91	
92	#if defined(CONFIG_GD32F470ZK_EVAL_GD25_FTL)
93	      /* And finally, use the FTL layer to wrap the MTD driver as a block
94	       * driver at /dev/mtdblockN, where N=minor device number.
95	       */
96	
97	      ret = ftl_initialize(minor, mtd);
98	      if (ret < 0)
99	        {
100	          syslog(LOG_ERR, "ERROR: Failed to initialize the FTL layer: %d\n",
101	                 ret);
102	          return ret;
103	        }
104	
105	#elif defined(CONFIG_GD32F470ZK_EVAL_GD25_NXFFS)
106	      /* Initialize to provide NXFFS on the MTD interface */
107	
108	      ret = nxffs_initialize(mtd);
109	      if (ret < 0)
110	        {
111	          syslog(LOG_ERR, "ERROR: NXFFS initialization failed: %d\n", ret);
112	          return ret;
113	        }
114	
115	      /* Mount the file system at /mnt/gd25 */
116	
117	      ret = nx_mount(NULL, "/mnt/gd25", "nxffs", 0, NULL);
118	      if (ret < 0)
119	        {
120	          syslog(LOG_ERR, "ERROR: Failed to mount the NXFFS volume: %d\n",
121	                 ret);
122	          return ret;
123	        }
124	
125	      syslog(LOG_INFO, "INFO: NXFFS volume /mnt/gd25 mount \
126	            spi flash success: %d\n", ret);
127	
128	#elif defined(CONFIG_GD32F470ZK_EVAL_GD25_LITTLEFS)
129	      /* Initialize to provide LittleFS on the MTD interface */
130	
131	      ret = register_mtddriver("/dev/spiflash", mtd, 0755, NULL);
132	      if (ret < 0)
133	        {
134	          syslog(LOG_ERR, "ERROR: Failed to register MTD: %d\n", ret);
135	          return ret;
136	        }
137	
138	      /* Mount the file system at /mnt/gd25 */
139	
140	      ret = nx_mount("/dev/spiflash", "/mnt/gd25", "littlefs", 0, NULL);
141	      if (ret < 0)
142	        {
143	          ret = nx_mount("/dev/spiflash", "/mnt/gd25", "littlefs", 0,
144	                         "forceformat");
145	          if (ret < 0)
146	            {
147	              ferr("ERROR: Failed to mount the FS volume: %d\n", ret);
148	              return ret;
149	            }
150	        }
151	
152	      syslog(LOG_INFO, "INFO: LittleFS volume /mnt/gd25 mount \
153	            spi flash success: %d\n", ret);
154	#endif
155	
156	      /* Now we are initialized */
157	
158	      initialized = true;
159	    }
160	
161	  UNUSED(ret);
162	
163	  return OK;
164	}
165	
