#ifdef CONFIG_SPI_EXCHANGE
static void ls2k300_spiio_exchange(FAR struct spi_dev_s *dev,
                                   FAR const void *txbuffer,
                                   FAR void *rxbuffer,
                                   size_t nwords)
{
  FAR struct ls2k300_spiio_priv_s *priv =
      (FAR struct ls2k300_spiio_priv_s *)dev;
  FAR const uint8_t *txptr = (FAR const uint8_t *)txbuffer;
  FAR uint8_t *rxptr = (FAR uint8_t *)rxbuffer;
  size_t i;

  if (nwords == 0)
    {
      return;
    }

  /* Start of transfer: assert CS with SPE|CSTART for the first byte */

  for (i = 0; i < nwords; i++)
    {
      /* Wait for TX buffer empty */

      if (spiio_idle_sr1(priv, SR1_TXA, SPIIO_TIMEOUT) < 0)
        {
          break;
        }

      /* Write TX data */

      if (txptr)
        {
          spiio_write_reg_byte(priv, LS2K300_SPIIO_DR, *txptr++);
        }
      else
        {
          spiio_write_reg_byte(priv, LS2K300_SPIIO_DR, 0x00);
        }

      /* First byte: SPE|CSTART to start transfer and assert CS.
       * Middle bytes: SPE|AUTOSUS to resume and keep CS asserted.
       * Last byte will be terminated below after we receive the data.
       */

      if (i == 0)
        {
          spiio_write_reg(priv, LS2K300_SPIIO_CR1,
                          CR1_SPE | CR1_CSTART | CR1_AUTOSUS);
        }
      else
        {
          spiio_write_reg(priv, LS2K300_SPIIO_CR1,
                          CR1_SPE | CR1_AUTOSUS);
        }

      /* Wait for EOT (byte transfer complete) */

      if (spiio_idle_sr1(priv, SR1_EOT, SPIIO_TIMEOUT) < 0)
        {
          break;
        }

      /* Clear EOT for next byte (except after last byte) */

      if (i < nwords - 1)
        {
          spiio_write_reg(priv, LS2K300_SPIIO_SR1, SR1_EOT);
        }

      /* Wait for RX data available */

      if (spiio_idle_sr1(priv, SR1_RXA, SPIIO_TIMEOUT) < 0)
        {
          break;
        }

      /* Read RX data */

      if (rxptr)
        {
          *rxptr++ = spiio_read_reg_byte(priv, LS2K300_SPIIO_DR);
        }
      else
        {
          spiio_read_reg_byte(priv, LS2K300_SPIIO_DR);
        }
    }

  /* End of transfer: set CSTART to deassert CS */

  spiio_write_reg(priv, LS2K300_SPIIO_CR1, CR1_SPE | CR1_CSTART);
}
#endif

