106	                                           uint32_t frequency)
107	{
108	  FAR struct ls2k300_spiio_priv_s *priv =
109	      (FAR struct ls2k300_spiio_priv_s *)dev;
110	  uint32_t cfg2;
111	  uint32_t brint;
112	  uint32_t brdec;
113	  uint32_t div;
114	
115	  if (frequency == 0)
116	    {
117	      frequency = priv->clock_freq / 2;
118	    }
119	
120	  div = priv->clock_freq / (2 * frequency);
121	  if (div < 1)
122	    {
123	      div = 1;
124	    }
125	
126	  brint = div / 2;
127	  if (brint < 1)
128	    {
129	      brint = 1;
130	    }
131	  if (brint > 255)
132	    {
133	      brint = 255;
134	    }
135	
136	  brdec = div - brint * 2;
137	  if (brdec > 3)
138	    {
139	      brdec = 3;
140	    }
141	
142	  cfg2 = spiio_read_reg(priv, LS2K300_SPIIO_CFG2);
143	  cfg2 &= ~(CFG2_BRINT_MASK | CFG2_BRDEC_MASK);
144	  cfg2 |= (brint << CFG2_BRINT_SHIFT) | brdec;
145	  spiio_write_reg(priv, LS2K300_SPIIO_CFG2, cfg2);
146	
147	  priv->frequency = priv->clock_freq / (2 * div);
148	  return priv->frequency;
