4	 * SPI Flash 驱动模板 - 基于 LS2K300 硬件 SPI2 控制器
5	 *
6	 * Hummingbird 2K300 板 SPI Flash 接线（LOONG-HAT 40PIN）：
7	 *   - SPI2_CLK:  GPIO64 (MAIN_FUNC) - J12 Pin23
8	 *   - SPI2_MISO: GPIO65 (MAIN_FUNC) - J12 Pin21
9	 *   - SPI2_MOSI: GPIO66 (MAIN_FUNC) - J12 Pin19
10	 *   - Flash CS:  GPIO85 (GPIO, 软件片选) - J12 Pin26
11	 *   - SPI2 基地址: 0x1610c000
12	 *   - APB 时钟: 200MHz
13	 *
14	 * 关键设计原则：
15	 *   1. DR 寄存器必须用 8 位访问（SPI_REG8），不能用 32 位（SPI_REG32）
16	 *   2. 每次传输必须等待 EOT 标志
17	 *   3. Flash 操作（erase/program）期间不能调用 spi2_bus_reset()
18	 *   4. 程序退出前必须释放 CS，否则 flash 可能卡死
19	 *   5. 启动时发送软件复位命令，恢复 flash 到已知状态
20	 ****************************************************************************/
21	
22	#include <nuttx/config.h>
23	#include <sys/ioctl.h>
24	#include <stdio.h>
25	#include <string.h>
26	#include <fcntl.h>
27	#include <errno.h>
28	#include <unistd.h>
29	#include <stdint.h>
30	
31	#include <nuttx/ioexpander/gpio.h>
32	#include <nuttx/arch.h>
33	
34	/****************************************************************************
35	 * Pre-processor Definitions
36	 ****************************************************************************/
37	
38	/* SPI2 控制器基地址 */
39	
40	#define SPI2_BASE               (0x8000000000000000UL | 0x1610c000UL)
41	
42	/* GENERAL_CFG5: SPI2/3 时钟门控 */
43	
44	#define LS_GENERAL_CFG5_ADDR    (0x8000000000000000UL | 0x16000114UL)
45	
46	/* SPI IO 寄存器偏移（LS2K300 手册 ch.10） */
47	
48	#define LS_SPI_IO_CR1           0x00
49	#define LS_SPI_IO_CR3           0x08
50	#define LS_SPI_IO_CR4           0x0c
51	#define LS_SPI_IO_SR1           0x14
52	#define LS_SPI_IO_CFG1          0x20
53	#define LS_SPI_IO_CFG2          0x24
54	#define LS_SPI_IO_CFG3          0x28
55	#define LS_SPI_IO_DR            0x40
56	
57	/* CR1 位 */
58	
59	#define LS_SPI_CR1_SPE          (1U << 0)
60	#define LS_SPI_CR1_CSTART       (1U << 1)
61	#define LS_SPI_CR1_AUTOSUS      (1U << 2)
62	
63	/* CFG1: 8-bit 帧，SPI Mode 0 */
64	
65	#define LS_SPI_CFG1_DSIZE_8BIT  (7U << 8)
66	
67	/* CFG2: 波特率分频 */
68	
69	#define LS_SPI_CFG2_BRINT_SHIFT 8
70	
71	/* CFG3: 主模式、全双工、软件 CS */
72	
73	#define LS_SPI_CFG3_MSTR        (1U << 0)
74	#define LS_SPI_CFG3_DIE         (1U << 2)
75	#define LS_SPI_CFG3_DOE         (1U << 3)
76	#define LS_SPI_CFG3_SSMODE_SW   (1U << 8)
77	
78	/* SR1 状态位 */
79	
80	#define LS_SPI_SR1_RXA          (1U << 0)
81	#define LS_SPI_SR1_TXA          (1U << 1)
82	#define LS_SPI_SR1_RXE          (1U << 4)
83	#define LS_SPI_SR1_EOT          (1U << 15)
84	
85	#define LS_SPI_SR1_W1C_FLAGS    (LS_SPI_SR1_EOT | (1U << 11) | \
86	                                 (1U << 10) | (1U << 9) | (1U << 8))
87	
88	/* 时钟配置 */
89	
90	#define SPI_APB_HZ              (200UL * 1000000UL)
91	#define SPI_CLOCK_HZ            1000000UL
92	#define SPI_WAIT_TIMEOUT_US     10000U
93	
94	/* Flash CS 引脚 */
95	
96	#define FLASH_CS_PIN            85
97	
98	/* SPI Flash 命令 */
99	
100	#define SPIFLASH_CMD_WRITE_ENABLE     0x06
101	#define SPIFLASH_CMD_READ_STATUS      0x05
102	#define SPIFLASH_CMD_READ_JEDEC_ID    0x9f
103	#define SPIFLASH_CMD_READ_DATA        0x03
104	#define SPIFLASH_CMD_PAGE_PROGRAM     0x02
105	#define SPIFLASH_CMD_SECTOR_ERASE_4K  0x20
106	#define SPIFLASH_CMD_ENABLE_RESET     0x66
107	#define SPIFLASH_CMD_RESET            0x99
108	#define SPIFLASH_STATUS_WIP           0x01
109	
110	/* Flash 参数 */
111	
112	#define SPIFLASH_SECTOR_SIZE          4096U
113	
114	/* 寄存器访问宏（⚠️ DR 必须用 8 位访问） */
115	
116	#define SPI_REG32(off)  (*(volatile uint32_t *)(SPI2_BASE + (off)))
117	#define SPI_REG8(off)   (*(volatile uint8_t *)(SPI2_BASE + (off)))
118	#define CFG5_REG        (*(volatile uint32_t *)LS_GENERAL_CFG5_ADDR)
119	
120	/****************************************************************************
121	 * Private Data
122	 ****************************************************************************/
123	
124	static int g_fd_flash_cs = -1;
125	
126	/****************************************************************************
127	 * Name: spi2_bus_reset
128	 *
129	 * Description:
130	 *   重置 SPI 总线状态。用于设备切换或错误恢复。
131	 *   ⚠️ 不要在 flash 操作（erase/program/read）中途调用！
132	 *      这会切换 CS 电平，中断正在进行的 flash 操作。
133	 *
134	 *   正确用法：仅在顶层操作入口调用，如：
135	 *   - 程序初始化时
136	 *   - ADC 读取后、Flash 操作前
137	 *   - 程序退出前
138	 ****************************************************************************/
139	
140	static void spi2_bus_reset(void)
141	{
142	  uint32_t val;
143	  uint32_t i;
144	
145	  val = SPI_REG32(LS_SPI_IO_CR1);
146	  val &= ~(LS_SPI_CR1_CSTART | LS_SPI_CR1_AUTOSUS);
147	  SPI_REG32(LS_SPI_IO_CR1) = val;
148	
149	  SPI_REG32(LS_SPI_IO_CR4) = 0;
150	  SPI_REG32(LS_SPI_IO_CR3) = 0;
151	  up_udelay(10);
152	
153	  SPI_REG32(LS_SPI_IO_SR1) = LS_SPI_SR1_W1C_FLAGS;
154	
155	  for (i = 0; i < 4; i++)
156	    {
157	      if (SPI_REG32(LS_SPI_IO_SR1) & LS_SPI_SR1_RXE)
158	        {
159	          break;
160	        }
161	
162	      (void)SPI_REG8(LS_SPI_IO_DR);  /* ⚠️ 8 位读取 */
163	    }
164	
165	  SPI_REG32(LS_SPI_IO_CR1) = LS_SPI_CR1_SPE;
166	  ioctl(g_fd_flash_cs, GPIOC_WRITE, 1);  /* 释放 CS */
167	  up_udelay(10);
168	}
169	
170	/****************************************************************************
171	 * Name: spi2_abort
172	 *
173	 * Description:
174	 *   传输超时时中止当前操作，释放 CS。
175	 ****************************************************************************/
176	
177	static void spi2_abort(void)
178	{
179	  uint32_t val;
180	  uint32_t i;
181	
182	  val = SPI_REG32(LS_SPI_IO_CR1);
183	  val &= ~(LS_SPI_CR1_CSTART | LS_SPI_CR1_AUTOSUS);
184	  SPI_REG32(LS_SPI_IO_CR1) = val;
185	
186	  SPI_REG32(LS_SPI_IO_CR4) = 0;
187	  SPI_REG32(LS_SPI_IO_CR3) = 0;
188	  up_udelay(10);
189	
190	  SPI_REG32(LS_SPI_IO_SR1) = LS_SPI_SR1_W1C_FLAGS;
191	
192	  for (i = 0; i < 4; i++)
193	    {
194	      if (SPI_REG32(LS_SPI_IO_SR1) & LS_SPI_SR1_RXE)
195	        {
196	          break;
197	        }
198	
199	      (void)SPI_REG8(LS_SPI_IO_DR);
200	    }
201	
202	  ioctl(g_fd_flash_cs, GPIOC_WRITE, 1);
203	  up_udelay(1);
204	}
205	
206	/****************************************************************************
207	 * Name: spi2_xfer_byte
208	 *
209	 * Description:
210	 *   单字节 SPI 全双工传输。
211	 *   ⚠️ DR 寄存器必须用 8 位访问！32 位访问会导致数据错位。
212	 *   ⚠️ 必须等待 EOT 标志，不能只等 RXA。
213	 ****************************************************************************/
214	
215	static int spi2_xfer_byte(uint8_t tx, uint8_t *rx)
216	{
217	  uint32_t val;
218	  uint32_t sr1;
219	  uint32_t i;
220	
221	  /* 1. 使能 SPI */
222	
223	  val = SPI_REG32(LS_SPI_IO_CR1);
224	  val |= LS_SPI_CR1_SPE;
225	  SPI_REG32(LS_SPI_IO_CR1) = val;
226	
227	  /* 2. 清 CSTART/AUTOSUS */
228	
229	  val = SPI_REG32(LS_SPI_IO_CR1);
230	  val &= ~(LS_SPI_CR1_CSTART | LS_SPI_CR1_AUTOSUS);
231	  SPI_REG32(LS_SPI_IO_CR1) = val;
232	
233	  /* 3. 清 W1C 状态标志 */
234	
235	  SPI_REG32(LS_SPI_IO_SR1) = LS_SPI_SR1_W1C_FLAGS;
236	
237	  /* 4. TSIZE = 0（单帧） */
238	
239	  SPI_REG32(LS_SPI_IO_CR3) = 0;
240	
241	  /* 5. 等待 TX FIFO 可写 */
242	
243	  for (i = 0; i < SPI_WAIT_TIMEOUT_US; i++)
244	    {
245	      sr1 = SPI_REG32(LS_SPI_IO_SR1);
246	      if (sr1 & LS_SPI_SR1_TXA)
247	        {
248	          break;
249	        }
250	
251	      up_udelay(1);
252	    }
253	
254	  if (i >= SPI_WAIT_TIMEOUT_US)
255	    {
256	      spi2_abort();
257	      return -1;
258	    }
259	
260	  /* 6. 写入 TX 字节（⚠️ 8 位写入！） */
261	
262	  SPI_REG8(LS_SPI_IO_DR) = tx;
263	
264	  /* 7. 启动传输：只置 CSTART，不置 AUTOSUS */
265	
266	  val = SPI_REG32(LS_SPI_IO_CR1);
267	  val |= LS_SPI_CR1_CSTART;
268	  SPI_REG32(LS_SPI_IO_CR1) = val;
269	
270	  /* 8. 等待 EOT（传输结束标志） */
271	
272	  for (i = 0; i < SPI_WAIT_TIMEOUT_US; i++)
273	    {
274	      sr1 = SPI_REG32(LS_SPI_IO_SR1);
275	      if (sr1 & LS_SPI_SR1_EOT)
276	        {
277	          break;
278	        }
279	
280	      up_udelay(1);
281	    }
282	
283	  if (i >= SPI_WAIT_TIMEOUT_US)
284	    {
285	      spi2_abort();
286	      return -1;
287	    }
288	
289	  /* 9. 清除 EOT */
290	
291	  SPI_REG32(LS_SPI_IO_SR1) = LS_SPI_SR1_EOT;
292	
293	  /* 10. 等待 RX FIFO 有数据 */
294	
295	  for (i = 0; i < SPI_WAIT_TIMEOUT_US; i++)
296	    {
297	      sr1 = SPI_REG32(LS_SPI_IO_SR1);
298	      if (sr1 & LS_SPI_SR1_RXA)
299	        {
300	          break;
301	        }
302	
303	      up_udelay(1);
304	    }
305	
306	  if (i >= SPI_WAIT_TIMEOUT_US)
307	    {
308	      spi2_abort();
309	      return -1;
310	    }
311	
312	  /* 11. 读取 RX 字节（⚠️ 8 位读取！） */
313	
314	  if (rx != NULL)
315	    {
316	      *rx = SPI_REG8(LS_SPI_IO_DR);
317	    }
318	  else
319	    {
320	      (void)SPI_REG8(LS_SPI_IO_DR);
321	    }
322	
323	  return 0;
324	}
325	
326	/****************************************************************************
327	 * Name: spi2_init
328	 *
329	 * Description:
330	 *   初始化 SPI2 控制器和 Flash CS GPIO。
331	 ****************************************************************************/
332	
333	static int spi2_init(void)
334	{
335	  uint32_t brint;
336	  int ret;
337	
338	  /* CS GPIO 初始化 */
339	
340	  ret = pinctrl_set_gpio_function(FLASH_CS_PIN);
341	  if (ret < 0)
342	    {
343	      printf("[SPIFLASH] ERROR: pinctrl GPIO%d: %d\n", FLASH_CS_PIN, ret);
344	      return ret;
345	    }
346	
347	  char path[32];
348	  snprintf(path, sizeof(path), "/dev/gpio%d", FLASH_CS_PIN);
349	  g_fd_flash_cs = open(path, O_RDWR);
350	  if (g_fd_flash_cs < 0)
351	    {
352	      return -errno;
353	    }
354	
355	  ret = ioctl(g_fd_flash_cs, GPIOC_SETPINTYPE, (unsigned long)GPIO_OUTPUT_PIN);
356	  if (ret < 0)
357	    {
358	      return -errno;
359	    }
360	
361	  ioctl(g_fd_flash_cs, GPIOC_WRITE, 1);  /* CS 高（空闲） */
362	
363	  /* 使能 SPI2/3 时钟门控 */
364	
365	  CFG5_REG |= (0x3u << 17);
366	
367	  /* CFG3: 主模式、全双工、软件 CS */
368	
369	  SPI_REG32(LS_SPI_IO_CFG3) = LS_SPI_CFG3_MSTR | LS_SPI_CFG3_DIE |
370	                               LS_SPI_CFG3_DOE | LS_SPI_CFG3_SSMODE_SW;
371	
372	  /* CFG1: 8-bit 帧，SPI Mode 0 */
373	
374	  SPI_REG32(LS_SPI_IO_CFG1) = LS_SPI_CFG1_DSIZE_8BIT;
375	
376	  /* CFG2: 波特率分频 */
377	
378	  brint = SPI_APB_HZ / SPI_CLOCK_HZ;
379	  if (brint < 2) brint = 2;
380	  if (brint > 255) brint = 255;
381	  SPI_REG32(LS_SPI_IO_CFG2) = brint << LS_SPI_CFG2_BRINT_SHIFT;
382	
383	  /* CR1: 使能 SPI */
384	
385	  SPI_REG32(LS_SPI_IO_CR1) = LS_SPI_CR1_SPE;
386	
387	  ioctl(g_fd_flash_cs, GPIOC_WRITE, 1);
388	  up_udelay(10);
389	
390	  return OK;
391	}
392	
393	/****************************************************************************
394	 * Flash 底层操作
395	 ****************************************************************************/
396	
397	static void flash_cs_select(void)
398	{
399	  ioctl(g_fd_flash_cs, GPIOC_WRITE, 0);
400	  up_udelay(1);
401	}
402	
403	static void flash_cs_deselect(void)
404	{
405	  ioctl(g_fd_flash_cs, GPIOC_WRITE, 1);
406	  up_udelay(10);  /* flash 需要较长的 CS 高电平时间 */
407	}
408	
409	static uint8_t flash_xfer(uint8_t tx)
410	{
411	  uint8_t rx = 0;
412	  spi2_xfer_byte(tx, &rx);
413	  return rx;
414	}
415	
416	/****************************************************************************
417	 * Name: flash_software_reset
418	 *
419	 * Description:
420	 *   发送软件复位命令，恢复 flash 到已知状态。
421	 *   必须在程序启动时调用，防止上次运行残留的脏状态。
422	 ****************************************************************************/
423	
424	static void flash_software_reset(void)
425	{
426	  flash_cs_select();
427	  flash_xfer(SPIFLASH_CMD_ENABLE_RESET);
428	  flash_cs_deselect();
429	  up_udelay(1);
430	
431	  flash_cs_select();
432	  flash_xfer(SPIFLASH_CMD_RESET);
433	  flash_cs_deselect();
434	  up_mdelay(30);  /* flash 复位需要约 30ms */
435	}
436	
437	static void flash_read_jedec_id(uint8_t id[3])
438	{
439	  flash_cs_select();
440	  flash_xfer(SPIFLASH_CMD_READ_JEDEC_ID);
441	  id[0] = flash_xfer(0xff);
442	  id[1] = flash_xfer(0xff);
443	  id[2] = flash_xfer(0xff);
444	  flash_cs_deselect();
445	}
446	
447	static uint8_t flash_read_status(void)
448	{
449	  uint8_t status;
450	
451	  flash_cs_select();
452	  flash_xfer(SPIFLASH_CMD_READ_STATUS);
453	  status = flash_xfer(0xff);
454	  flash_cs_deselect();
455	
456	  return status;
457	}
458	
459	static void flash_write_enable(void)
460	{
461	  flash_cs_select();
462	  flash_xfer(SPIFLASH_CMD_WRITE_ENABLE);
463	  flash_cs_deselect();
464	  up_udelay(1);
465	}
466	
467	static int flash_wait_ready(FAR const char *op)
468	{
469	  uint8_t status;
470	  int i;
471	
472	  for (i = 0; i < 500; i++)
473	    {
474	      status = flash_read_status();
475	      if ((status & SPIFLASH_STATUS_WIP) == 0)
476	        {
477	          return OK;
478	        }
479	
480	      up_mdelay(10);
481	    }
482	
483	  printf("[SPIFLASH] %s timeout, status=0x%02x\n", op, status);
484	  return -ETIMEDOUT;
485	}
486	
487	static int flash_sector_erase(uint32_t addr)
488	{
489	  flash_write_enable();
490	
491	  flash_cs_select();
492	  flash_xfer(SPIFLASH_CMD_SECTOR_ERASE_4K);
493	  flash_xfer((uint8_t)(addr >> 16));
494	  flash_xfer((uint8_t)(addr >> 8));
495	  flash_xfer((uint8_t)addr);
496	  flash_cs_deselect();
497	
498	  return flash_wait_ready("erase");
499	}
500	
501	static int flash_page_program(uint32_t addr, FAR const uint8_t *data,
502	                              uint32_t len)
503	{
504	  uint32_t i;
505	
506	  flash_write_enable();
507	
508	  flash_cs_select();
509	  flash_xfer(SPIFLASH_CMD_PAGE_PROGRAM);
510	  flash_xfer((uint8_t)(addr >> 16));
511	  flash_xfer((uint8_t)(addr >> 8));
512	  flash_xfer((uint8_t)addr);
513	
514	  for (i = 0; i < len; i++)
515	    {
516	      flash_xfer(data[i]);
517	    }
518	
519	  flash_cs_deselect();
520	
521	  return flash_wait_ready("program");
522	}
523	
524	static void flash_read_data(uint32_t addr, FAR uint8_t *data, uint32_t len)
525	{
526	  uint32_t i;
527	
528	  flash_cs_select();
529	  flash_xfer(SPIFLASH_CMD_READ_DATA);
530	  flash_xfer((uint8_t)(addr >> 16));
531	  flash_xfer((uint8_t)(addr >> 8));
532	  flash_xfer((uint8_t)addr);
533	
534	  for (i = 0; i < len; i++)
535	    {
536	      data[i] = flash_xfer(0xff);
537	    }
538	
539	  flash_cs_deselect();
540	}
