static void ls2k300_spiio_select(FAR struct spi_dev_s *dev,
                                 uint32_t devid, bool selected)
{
  /* CS is managed externally via GPIO (e.g. GPIO85 for flash).
   * The SPIIO controller is configured for software CS (SSMODE_SW),
   * so the controller does not toggle CS automatically.
   * This callback is intentionally left as a no-op — the actual
   * GPIO CS control is handled at the board level.
   */
}

