static uint32_t ls2k300_spiio_send(FAR struct spi_dev_s *dev, uint32_t wd)
{
  FAR struct ls2k300_spiio_priv_s *priv =
      (FAR struct ls2k300_spiio_priv_s *)dev;

  if (spiio_idle_sr1(priv, SR1_TXA, SPIIO_TIMEOUT) < 0)
    {
      return 0;
    }

  spiio_write_reg_byte(priv, LS2K300_SPIIO_DR, (uint8_t)(wd & 0xff));

  /* Use CSTART only for the first byte after CS was asserted.
   * Subsequent bytes use SPE|AUTOSUS to keep CS asserted across the
   * entire multi-byte SPI command sequence.
   */

  if (priv->cs_active)
    {
      spiio_write_reg(priv, LS2K300_SPIIO_CR1,
                      CR1_SPE | CR1_CSTART | CR1_AUTOSUS);
      priv->cs_active = false;
    }
  else
    {
      spiio_write_reg(priv, LS2K300_SPIIO_CR1,
                      CR1_SPE | CR1_AUTOSUS);
    }

  if (spiio_idle_sr1(priv, SR1_EOT, SPIIO_TIMEOUT) < 0)
    {
      return 0;
    }

  spiio_write_reg(priv, LS2K300_SPIIO_SR1, SR1_EOT);

  if (spiio_idle_sr1(priv, SR1_RXA, SPIIO_TIMEOUT) < 0)
    {
      return 0;
    }

  return (uint32_t)spiio_read_reg_byte(priv, LS2K300_SPIIO_DR);
}

input.new_string:
static uint32_t ls2k300_spiio_send(FAR struct spi_dev_s *dev, uint32_t wd)
{
  FAR struct ls2k300_spiio_priv_s *priv =
      (FAR struct ls2k300_spiio_priv_s *)dev;
  uint32_t val;

  /* Clear CSTART/AUTOSUS before starting */

  val = spiio_read_reg(priv, LS2K300_SPIIO_CR1);
  val &= ~(CR1_CSTART | CR1_AUTOSUS);
  spiio_write_reg(priv, LS2K300_SPIIO_CR1, val);

  /* Clear W1C status flags */

  spiio_write_reg(priv, LS2K300_SPIIO_SR1, SR1_EOT);

  if (spiio_idle_sr1(priv, SR1_TXA, SPIIO_TIMEOUT) < 0)
    {
      return 0;
    }

  /* Write TX byte (8-bit access, as required by hardware) */

  spiio_write_reg_byte(priv, LS2K300_SPIIO_DR, (uint8_t)(wd & 0xff));

  /* Start transfer: ONLY CSTART, NEVER AUTOSUS!
   * AUTOSUS=1 causes EOT to never be set (hardware erratum).
   */

  val = spiio_read_reg(priv, LS2K300_SPIIO_CR1);
  val |= CR1_CSTART;
  spiio_write_reg(priv, LS2K300_SPIIO_CR1, val);

  /* Wait for EOT (End Of Transfer) */

  if (spiio_idle_sr1(priv, SR1_EOT, SPIIO_TIMEOUT) < 0)
    {
      return 0;
    }

  /* Clear EOT */

  spiio_write_reg(priv, LS2K300_SPIIO_SR1, SR1_EOT);

  /* Wait for RX data */

  if (spiio_idle_sr1(priv, SR1_RXA, SPIIO_TIMEOUT) < 0)
    {
      return 0;
    }

  return (uint32_t)spiio_read_reg_byte(priv, LS2K300_SPIIO_DR);
}

