        up_mdelay(30);         /* Wait for reset */

        /* Probe GD25 flash — select() handles CS via GPIO85 */

        FAR struct mtd_dev_s *mtd = gd25_initialize(spi, 0);
        if (mtd == NULL)
          {
            serr("ERROR: gd25_initialize failed on SPIIO2\n");
          }
        else
          {
            /* Register the MTD device */

            ret = register_mtddriver("/dev/spiflash", mtd, 0755, NULL);
            if (ret < 0)
              {
                serr("ERROR: register_mtddriver failed: %d\n", ret);
              }
            else
              {
                /* Create mount point and mount LittleFS */

                mkdir("/mnt/spiflash", 0777);

                ret = nx_mount("/dev/spiflash", "/mnt/spiflash",
                               "littlefs", 0, "autoformat");
                if (ret < 0)
                  {
                    serr("ERROR: Failed to mount LittleFS: %d\n", ret);
                  }
                else
                  {
                    _info("bringup: LittleFS mounted at /mnt/spiflash\n");
                  }
              }
          }
      }
  }
#endif

