81	static void ls2k300_spiio_select(FAR struct spi_dev_s *dev,
82	                                 uint32_t devid, bool selected)
83	{
84	  /* Flash CS is GPIO85, active-low.
85	   * GPIO register layout: per-pin byte access.
86	   *   DIR:  base + 0x800 + pin (1=output)
87	   *   OUT:  base + 0x900 + pin (1=high, 0=low)
88	   * GPIO85 is already configured as output in bringup.
89	   */
90	
91	  uintptr_t gpio_out = PHYS_TO_UNCACHED(LS2K300_GPIO_BASE) + 0x900;
92	
93	  if (selected)
94	    {
95	      putreg8(0, gpio_out + 85);  /* CS low (assert) */
96	    }
97	  else
98	    {
99	      putreg8(1, gpio_out + 85);  /* CS high (deassert) */
100	    }
101	}
