103	static uint32_t ls2k300_spiio_setfrequency(FAR struct spi_dev_s *dev,
104	                                           uint32_t frequency)
105	{
106	  FAR struct ls2k300_spiio_priv_s *priv =
107	      (FAR struct ls2k300_spiio_priv_s *)dev;
108	  uint32_t cfg2;
109	  uint32_t brint;
110	  uint32_t brdec;
111	  uint32_t div;
112	
113	  if (frequency == 0)
114	    {
115	      frequency = priv->clock_freq / 2;
116	    }
117	
118	  div = priv->clock_freq / (2 * frequency);
119	  if (div < 1)
120	    {
121	      div = 1;
122	    }
123	
124	  brint = div / 2;
125	  if (brint < 1)
126	    {
127	      brint = 1;
128	    }
129	  if (brint > 255)
130	    {
131	      brint = 255;
132	    }
133	
134	  brdec = div - brint * 2;
135	  if (brdec > 3)
136	    {
137	      brdec = 3;
138	    }
139	
140	  cfg2 = spiio_read_reg(priv, LS2K300_SPIIO_CFG2);
141	  cfg2 &= ~(CFG2_BRINT_MASK | CFG2_BRDEC_MASK);
142	  cfg2 |= (brint << CFG2_BRINT_SHIFT) | brdec;
143	  spiio_write_reg(priv, LS2K300_SPIIO_CFG2, cfg2);
144	
145	  priv->frequency = priv->clock_freq / (2 * div);
146	  return priv->frequency;
147	}
