199	static uint32_t ls2k300_spiio_send(FAR struct spi_dev_s *dev, uint32_t wd)
200	{
201	  FAR struct ls2k300_spiio_priv_s *priv =
202	      (FAR struct ls2k300_spiio_priv_s *)dev;
203	  uint32_t val;
204	
205	  /* Clear CSTART/AUTOSUS before starting */
206	
207	  val = spiio_read_reg(priv, LS2K300_SPIIO_CR1);
208	  val &= ~(CR1_CSTART | CR1_AUTOSUS);
209	  spiio_write_reg(priv, LS2K300_SPIIO_CR1, val);
210	
211	  /* Clear W1C status flags */
212	
213	  spiio_write_reg(priv, LS2K300_SPIIO_SR1, SR1_EOT);
214	
215	  if (spiio_idle_sr1(priv, SR1_TXA, SPIIO_TIMEOUT) < 0)
216	    {
217	      return 0;
218	    }
219	
220	  /* Write TX byte (8-bit access, as required by hardware) */
221	
222	  spiio_write_reg_byte(priv, LS2K300_SPIIO_DR, (uint8_t)(wd & 0xff));
223	
224	  /* Start transfer: ONLY CSTART, NEVER AUTOSUS!
225	   * AUTOSUS=1 causes EOT to never be set (hardware erratum).
226	   */
227	
228	  val = spiio_read_reg(priv, LS2K300_SPIIO_CR1);
229	  val |= CR1_CSTART;
230	  spiio_write_reg(priv, LS2K300_SPIIO_CR1, val);
231	
232	  /* Wait for EOT (End Of Transfer) */
233	
234	  if (spiio_idle_sr1(priv, SR1_EOT, SPIIO_TIMEOUT) < 0)
235	    {
236	      return 0;
237	    }
238	
239	  /* Clear EOT */
240	
241	  spiio_write_reg(priv, LS2K300_SPIIO_SR1, SR1_EOT);
242	
243	  /* Wait for RX data */
244	
245	  if (spiio_idle_sr1(priv, SR1_RXA, SPIIO_TIMEOUT) < 0)
246	    {
247	      return 0;
248	    }
249	
250	  return (uint32_t)spiio_read_reg_byte(priv, LS2K300_SPIIO_DR);
251	}
