271	      val &= ~(CR1_CSTART | CR1_AUTOSUS);
272	      spiio_write_reg(priv, LS2K300_SPIIO_CR1, val);
273	
274	      /* Clear W1C status flags */
275	
276	      spiio_write_reg(priv, LS2K300_SPIIO_SR1, SR1_EOT);
277	
278	      if (spiio_idle_sr1(priv, SR1_TXA, SPIIO_TIMEOUT) < 0)
279	        {
280	          break;
281	        }
282	
283	      if (txptr)
284	        {
285	          spiio_write_reg_byte(priv, LS2K300_SPIIO_DR, *txptr++);
286	        }
287	      else
288	        {
289	          spiio_write_reg_byte(priv, LS2K300_SPIIO_DR, 0x00);
290	        }
291	
292	      /* Start transfer: ONLY CSTART, NEVER AUTOSUS */
293	
294	      val = spiio_read_reg(priv, LS2K300_SPIIO_CR1);
295	      val |= CR1_CSTART;
296	      spiio_write_reg(priv, LS2K300_SPIIO_CR1, val);
297	
298	      if (spiio_idle_sr1(priv, SR1_EOT, SPIIO_TIMEOUT) < 0)
299	        {
300	          break;
301	        }
302	
303	      spiio_write_reg(priv, LS2K300_SPIIO_SR1, SR1_EOT);
304	
305	      if (spiio_idle_sr1(priv, SR1_RXA, SPIIO_TIMEOUT) < 0)
306	        {
307	          break;
308	        }
309	
310	      if (rxptr)
311	        {
312	          *rxptr++ = spiio_read_reg_byte(priv, LS2K300_SPIIO_DR);
313	        }
314	      else
315	        {
316	          spiio_read_reg_byte(priv, LS2K300_SPIIO_DR);
317	        }
318	    }
319	}
