static void ls2k300_spiio_select(FAR struct spi_dev_s *dev,
                                 uint32_t devid, bool selected)
{
  /* Flash CS is GPIO85, active-low.
   * GPIO register layout: per-pin byte access.
   *   DIR:  base + 0x800 + pin (1=output)
   *   OUT:  base + 0x900 + pin (1=high, 0=low)
   * GPIO85 is already configured as output in bringup.
   */

  uintptr_t gpio_out = PHYS_TO_UNCACHED(LS2K300_GPIO_BASE) + 0x900;

  if (selected)
    {
      putreg8(0, gpio_out + 85);  /* CS low (assert) */
    }
  else
    {
      putreg8(1, gpio_out + 85);  /* CS high (deassert) */
    }
}

input.new_string:
static void ls2k300_spiio_select(FAR struct spi_dev_s *dev,
                                 uint32_t devid, bool selected)
{
  /* Flash CS is GPIO85, active-low.
   * GPIO register layout: per-pin byte access.
   *   DIR:  base + 0x800 + pin (1=output)
   *   OUT:  base + 0x900 + pin (1=high, 0=low)
   *   IN:   base + 0xa00 + pin (actual pin level)
   */

  uintptr_t gpio_base = PHYS_TO_UNCACHED(LS2K300_GPIO_BASE);
  uint8_t dir;
  uint8_t out;
  uint8_t in;

  if (selected)
    {
      putreg8(0, gpio_base + 0x900 + 85);  /* CS low (assert) */
    }
  else
    {
      putreg8(1, gpio_base + 0x900 + 85);  /* CS high (deassert) */
    }

  /* Debug: verify GPIO85 state */

  dir = getreg8(gpio_base + 0x800 + 85);
  out = getreg8(gpio_base + 0x900 + 85);
  in  = getreg8(gpio_base + 0xa00 + 85);
  _info("select(%s): GPIO85 DIR=%d OUT=%d IN=%d\n",
        selected ? "CS_L" : "CS_H", dir, out, in);
}

