  _info("bringup: SPIIO2 SPI Flash (late init)\n");

  /* Re-check pinmux region accessibility */

  {
    volatile uint32_t *pinmux =
        (volatile uint32_t *)PHYS_TO_UNCACHED(0x16000490);
    _info("SPIIO2: pinmux@490=0x%08" PRIx32 "\n", *pinmux);
  }

  /* Configure GPIO85: pinmux=GPIO, dir=output, out=high (CS idle) */

  ls_pinmux_pin_setup(85, LS_PINMUX_MODE_AS_GPIO);
  writeb(1, (volatile void *)(PHYS_TO_UNCACHED(LS2K300_GPIO_BASE) + 0x800 + 85));
  writeb(1, (volatile void *)(PHYS_TO_UNCACHED(LS2K300_GPIO_BASE) + 0x900 + 85));

  /* Verify GPIO85 state */

  {
    uintptr_t gpio_base = PHYS_TO_UNCACHED(LS2K300_GPIO_BASE);
    uint8_t dir = *(volatile uint8_t *)(gpio_base + 0x800 + 85);
    uint8_t out = *(volatile uint8_t *)(gpio_base + 0x900 + 85);
    uint8_t in  = *(volatile uint8_t *)(gpio_base + 0xa00 + 85);
    _info("SPIIO2: GPIO85 DIR=%d OUT=%d IN=%d\n", dir, out, in);
  }

  {
    FAR struct spi_dev_s *spi = ls2k300_spiio_initialize(0);
