        {
          uint8_t id0, id1, id2;
          SPI_SELECT(spi, SPIDEV_FLASH(0), true);
          SPI_SEND(spi, 0x9f);
          id0 = SPI_SEND(spi, 0xff);
          id1 = SPI_SEND(spi, 0xff);
          id2 = SPI_SEND(spi, 0xff);
          SPI_SELECT(spi, SPIDEV_FLASH(0), false);
          _info("SPIIO2: JEDEC ID = %02x %02x %02x\n", id0, id1, id2);
