int ls2k300_bringup(void)
{
  int ret = OK;

  _info("bringup: start\n");

  /* Reconfigure DMWIN0 to cover the FULL physical address space.
   * U-Boot may set a narrow DMWIN0 that doesn't include the chip config
   * region (0x16000xxx), making pinmux and CFG5 inaccessible.
   * Value: VSEG=0x8000 (uncached KSEG1), PLV0 enabled, full address range.
   */

  __asm__ __volatile__(
      "li.d $t0, 0x800000000000000f\n"
      "csrwr $t0, 0x180\n"  /* LOONGARCH_CSR_DMWIN0 */
      ::: "$t0", "memory");

  ls2k300_hardware_init();

