93	                                           uint32_t frequency)
94	{
95	  FAR struct ls2k300_spiio_priv_s *priv =
96	      (FAR struct ls2k300_spiio_priv_s *)dev;
97	  uint32_t cfg2;
98	  uint32_t brint;
99	  uint32_t brdec;
100	  uint32_t div;
101	
102	  if (frequency == 0)
103	    {
104	      frequency = priv->clock_freq / 2;
105	    }
106	
107	  div = priv->clock_freq / (2 * frequency);
108	  if (div < 1)
109	    {
110	      div = 1;
111	    }
112	
113	  brint = div / 2;
114	  if (brint < 1)
115	    {
116	      brint = 1;
117	    }
118	  if (brint > 255)
119	    {
120	      brint = 255;
121	    }
122	
123	  brdec = div - brint * 2;
124	  if (brdec > 3)
125	    {
126	      brdec = 3;
127	    }
128	
129	  cfg2 = spiio_read_reg(priv, LS2K300_SPIIO_CFG2);
130	  cfg2 &= ~(CFG2_BRINT_MASK | CFG2_BRDEC_MASK);
131	  cfg2 |= (brint << CFG2_BRINT_SHIFT) | brdec;
132	  spiio_write_reg(priv, LS2K300_SPIIO_CFG2, cfg2);
133	
134	  priv->frequency = priv->clock_freq / (2 * div);
135	  return priv->frequency;
136	}
