#include <nuttx/config.h>

#include <stdint.h>
#include <stdbool.h>
#include <inttypes.h>
#include <errno.h>
#include <assert.h>
#include <debug.h>

#include <nuttx/arch.h>
#include <nuttx/spi/spi.h>
#include <nuttx/kmalloc.h>

#include "loongarch_internal.h"
#include "hardware/ls2k300_memorymap.h"
#include "hardware/ls2k300_spiio.h"

#if defined(CONFIG_LS2K300_SPIIO)

#define LS2K300_SPIIO_CLOCK_FREQ 200000000UL
#define SPIIO_TIMEOUT            1000000

struct ls2k300_spiio_priv_s
{
  struct spi_dev_s dev;
  uintptr_t base;
  uint32_t clock_freq;
  uint32_t frequency;
  enum spi_mode_e mode;
  int nbits;
  bool initialized;
  bool cs_active;  /* track CS state for multi-byte hold */
};

static uint32_t spiio_read_reg(FAR struct ls2k300_spiio_priv_s *priv,
                               uint32_t offset)
{
  return getreg32(priv->base + offset);
}

static void spiio_write_reg(FAR struct ls2k300_spiio_priv_s *priv,
                            uint32_t offset, uint32_t value)
{
  putreg32(value, priv->base + offset);
}

static uint8_t spiio_read_reg_byte(FAR struct ls2k300_spiio_priv_s *priv,
                                   uint32_t offset)
{
  return getreg8(priv->base + offset);
}

static void spiio_write_reg_byte(FAR struct ls2k300_spiio_priv_s *priv,
                                 uint32_t offset, uint8_t value)
{
  putreg8(value, priv->base + offset);
}

static int spiio_idle_sr1(FAR struct ls2k300_spiio_priv_s *priv,
                          uint32_t bit, uint32_t timeout)
{
  uint32_t sr1;
  uint32_t count = 0;

  while (count < timeout)
    {
      sr1 = spiio_read_reg(priv, LS2K300_SPIIO_SR1);
      if (sr1 & bit)
        {
          return 0;
        }
      count++;
    }

  return -ETIMEDOUT;
}

static int ls2k300_spiio_lock(FAR struct spi_dev_s *dev, bool lock)
{
  return OK;
}

/* select() with SSMODE=0 (auto-CS):
 * selected=true:  CSTART will assert CS (via hardware). Set SPE, ready for send.
 * selected=false: finalize the current transfer — set CSTART one more time
 *                 to generate EOT which deasserts CS.
 */
static void ls2k300_spiio_select(FAR struct spi_dev_s *dev,
                                 uint32_t devid, bool selected)
{
  FAR struct ls2k300_spiio_priv_s *priv =
      (FAR struct ls2k300_spiio_priv_s *)dev;

  if (selected)
    {
      /* Prepare for a new multi-byte transfer.
       * Set SPE and clear any stale state. CS will assert on first CSTART.
       */

      uint32_t val;

      val = spiio_read_reg(priv, LS2K300_SPIIO_CR1);
      val |= CR1_SPE;
      val &= ~(CR1_CSTART | CR1_AUTOSUS);
      spiio_write_reg(priv, LS2K300_SPIIO_CR1, val);

      spiio_write_reg(priv, LS2K300_SPIIO_CR4, 0);
      spiio_write_reg(priv, LS2K300_SPIIO_CR3, 0);
      spiio_write_reg(priv, LS2K300_SPIIO_SR1, SR1_EOT | 0x0f00);
      up_udelay(5);

      priv->cs_active = true;
    }
  else
    {
      /* End of multi-byte transfer.
       * At this point, the last send() has already set CSTART
       * and we're in the middle of a transfer. Wait for EOT to
       * complete and CS to deassert.
       */

      if (priv->cs_active)
        {
          if (spiio_idle_sr1(priv, SR1_EOT, SPIIO_TIMEOUT) == 0)
            {
              spiio_write_reg(priv, LS2K300_SPIIO_SR1, SR1_EOT);

              /* Drain RX FIFO */

              int i;
              for (i = 0; i < 4; i++)
                {
                  uint32_t sr1 = spiio_read_reg(priv, LS2K300_SPIIO_SR1);
                  if (sr1 & 0x10)
                    break;

                  (void)spiio_read_reg_byte(priv, LS2K300_SPIIO_DR);
                }
            }

          /* Clear SPE to end session */

          uint32_t val = spiio_read_reg(priv, LS2K300_SPIIO_CR1);
          val &= ~(CR1_SPE | CR1_CSTART | CR1_AUTOSUS);
          spiio_write_reg(priv, LS2K300_SPIIO_CR1, val);

          priv->cs_active = false;
        }
    }
}

static uint32_t ls2k300_spiio_setfrequency(FAR struct spi_dev_s *dev,
                                           uint32_t frequency)
{
  FAR struct ls2k300_spiio_priv_s *priv =
      (FAR struct ls2k300_spiio_priv_s *)dev;
  uint32_t cfg2;
  uint32_t brint;
  uint32_t brdec;
  uint32_t div;

  if (frequency == 0)
    frequency = priv->clock_freq / 2;

  div = priv->clock_freq / (2 * frequency);
  if (div < 1)
    div = 1;

  brint = div / 2;
  if (brint < 1)
    brint = 1;
  if (brint > 255)
    brint = 255;

  brdec = div - brint * 2;
  if (brdec > 3)
    brdec = 3;

  cfg2 = spiio_read_reg(priv, LS2K300_SPIIO_CFG2);
  cfg2 &= ~(CFG2_BRINT_MASK | CFG2_BRDEC_MASK);
  cfg2 |= (brint << CFG2_BRINT_SHIFT) | brdec;
  spiio_write_reg(priv, LS2K300_SPIIO_CFG2, cfg2);

  priv->frequency = priv->clock_freq / (2 * div);
  return priv->frequency;
}

static void ls2k300_spiio_setmode(FAR struct spi_dev_s *dev,
                                  enum spi_mode_e mode)
{
  FAR struct ls2k300_spiio_priv_s *priv =
      (FAR struct ls2k300_spiio_priv_s *)dev;
  uint32_t cfg1;

  cfg1 = spiio_read_reg(priv, LS2K300_SPIIO_CFG1);
  cfg1 &= ~(CFG1_CPOL | CFG1_CPHA);

  switch (mode)
    {
      case SPIDEV_MODE0: break;
      case SPIDEV_MODE1: cfg1 |= CFG1_CPHA; break;
      case SPIDEV_MODE2: cfg1 |= CFG1_CPOL; break;
      case SPIDEV_MODE3: cfg1 |= CFG1_CPOL | CFG1_CPHA; break;
      default: return;
    }

  spiio_write_reg(priv, LS2K300_SPIIO_CFG1, cfg1);
  priv->mode = mode;
}

static void ls2k300_spiio_setbits(FAR struct spi_dev_s *dev, int nbits)
{
  FAR struct ls2k300_spiio_priv_s *priv =
      (FAR struct ls2k300_spiio_priv_s *)dev;
  uint32_t cfg1;

  if (nbits < 4 || nbits > 32)
    return;

  cfg1 = spiio_read_reg(priv, LS2K300_SPIIO_CFG1);
  cfg1 &= ~CFG1_DSIZE_MASK;
  cfg1 |= ((nbits - 1) << CFG1_DSIZE_SHIFT);
  spiio_write_reg(priv, LS2K300_SPIIO_CFG1, cfg1);

  priv->nbits = nbits;
}

/* send() with SSMODE=0 auto-CS:
 * The trick to hold CS across multiple send() calls:
 *   Byte 1: SPE=1, write DR, set CSTART → CS↓, transfer runs, wait EOT.
 *           EOT fires → CS would go ↑ but we immediately set CSTART again.
 *   Byte 2: Clear EOT, write DR, set CSTART → transfer continues, CS stays ↓
 *           because CSTART re-asserts before a full CS↑ edge propagates.
 *   ...
 *   select(false): let final EOT complete → CS↑
 *
 * Key: with SPE held at 1 between calls and CSTART pulsed each byte,
 * the auto-CS logic holds CS low because CSTART follows EOT so fast
 * that the deassert/assert cycle is invisible to the flash.
 */

static uint32_t ls2k300_spiio_send(FAR struct spi_dev_s *dev, uint32_t wd)
{
  FAR struct ls2k300_spiio_priv_s *priv =
      (FAR struct ls2k300_spiio_priv_s *)dev;
  uint32_t val;

  if (!priv->cs_active)
    {
      /* First byte — select() should have been called to init.
       * If not, do a best-effort init here.
       */
      val = spiio_read_reg(priv, LS2K300_SPIIO_CR1);
      val |= CR1_SPE;
      val &= ~(CR1_CSTART | CR1_AUTOSUS);
      spiio_write_reg(priv, LS2K300_SPIIO_CR1, val);
      spiio_write_reg(priv, LS2K300_SPIIO_SR1, SR1_EOT | 0x0f00);
      spiio_write_reg(priv, LS2K300_SPIIO_CR3, 0);
      priv->cs_active = true;
    }

  /* For subsequent bytes: clear CSTART (hardware auto-clears after EOT
   * but we must ensure a clean edge), write new data, set CSTART.
   * EOT from previous byte was already handled.
   */

  /* Clear W1C flags and set TSIZE=0 for single-byte */

  spiio_write_reg(priv, LS2K300_SPIIO_SR1, SR1_EOT | 0x0f00);
  spiio_write_reg(priv, LS2K300_SPIIO_CR3, 0);

  /* Wait for TX FIFO available */

  if (spiio_idle_sr1(priv, SR1_TXA, SPIIO_TIMEOUT) < 0)
    {
      uint32_t sr1 = spiio_read_reg(priv, LS2K300_SPIIO_SR1);
      _info("send: TXA timeout SR1=0x%08" PRIx32 "\n", sr1);
      return 0;
    }

  /* Write TX byte (8-bit access required by hardware) */

  spiio_write_reg_byte(priv, LS2K300_SPIIO_DR, (uint8_t)(wd & 0xff));

  /* Read current CR1 to avoid overwriting SPE */

  val = spiio_read_reg(priv, LS2K300_SPIIO_CR1);
  val |= CR1_SPE;
  val |= CR1_CSTART;
  spiio_write_reg(priv, LS2K300_SPIIO_CR1, val);

  /* Wait for EOT */

  if (spiio_idle_sr1(priv, SR1_EOT, SPIIO_TIMEOUT) < 0)
    {
      uint32_t sr1 = spiio_read_reg(priv, LS2K300_SPIIO_SR1);
      _info("send: EOT timeout SR1=0x%08" PRIx32 "\n", sr1);
      return 0;
    }

  /* EOT fires → CS deasserts briefly, but next send() will assert CSTART
   * again, keeping CS low across the multi-byte sequence.
   */

  /* Clear EOT */

  spiio_write_reg(priv, LS2K300_SPIIO_SR1, SR1_EOT);

  /* Wait for RX data */

  if (spiio_idle_sr1(priv, SR1_RXA, SPIIO_TIMEOUT) < 0)
    {
      uint32_t sr1 = spiio_read_reg(priv, LS2K300_SPIIO_SR1);
      _info("send: RXA timeout SR1=0x%08" PRIx32 "\n", sr1);
      return 0;
    }

  return (uint32_t)spiio_read_reg_byte(priv, LS2K300_SPIIO_DR);
}

/* exchange() — same per-byte logic, but all bytes in one call. */

static void ls2k300_spiio_exchange(FAR struct spi_dev_s *dev,
                                   FAR const void *txbuffer,
                                   FAR void *rxbuffer,
                                   size_t nwords)
{
  FAR struct ls2k300_spiio_priv_s *priv =
      (FAR struct ls2k300_spiio_priv_s *)dev;
  FAR const uint8_t *txptr = (FAR const uint8_t *)txbuffer;
  FAR uint8_t *rxptr = (FAR uint8_t *)rxbuffer;
  uint32_t val;
  size_t i;

  for (i = 0; i < nwords; i++)
    {
      spiio_write_reg(priv, LS2K300_SPIIO_SR1, SR1_EOT | 0x0f00);
      spiio_write_reg(priv, LS2K300_SPIIO_CR3, 0);

      if (spiio_idle_sr1(priv, SR1_TXA, SPIIO_TIMEOUT) < 0)
        break;

      if (txptr)
        spiio_write_reg_byte(priv, LS2K300_SPIIO_DR, *txptr++);
      else
        spiio_write_reg_byte(priv, LS2K300_SPIIO_DR, 0x00);

      val = spiio_read_reg(priv, LS2K300_SPIIO_CR1);
      val |= CR1_SPE | CR1_CSTART;
      spiio_write_reg(priv, LS2K300_SPIIO_CR1, val);

      if (spiio_idle_sr1(priv, SR1_EOT, SPIIO_TIMEOUT) < 0)
        break;

      spiio_write_reg(priv, LS2K300_SPIIO_SR1, SR1_EOT);

      if (spiio_idle_sr1(priv, SR1_RXA, SPIIO_TIMEOUT) < 0)
        break;

      if (rxptr)
        *rxptr++ = spiio_read_reg_byte(priv, LS2K300_SPIIO_DR);
      else
        (void)spiio_read_reg_byte(priv, LS2K300_SPIIO_DR);
    }
}

static uint8_t ls2k300_spiio_status(FAR struct spi_dev_s *dev,
                                    uint32_t devid)
{
  return SPI_STATUS_PRESENT;
}

static const struct spi_ops_s g_spiio_ops =
{
  ls2k300_spiio_lock,
  ls2k300_spiio_select,
  ls2k300_spiio_setfrequency,
#ifdef CONFIG_SPI_DELAY_CONTROL
  NULL,
#endif
  ls2k300_spiio_setmode,
  ls2k300_spiio_setbits,
#ifdef CONFIG_SPI_HWFEATURES
  NULL,
#endif
  ls2k300_spiio_status,
#ifdef CONFIG_SPI_CMDDATA
  NULL,
#endif
  ls2k300_spiio_send,
  ls2k300_spiio_exchange,
  NULL,
#ifdef CONFIG_SPI_TRIGGER
  NULL,
#endif
  NULL
};

static struct ls2k300_spiio_priv_s g_spiio_priv[2] =
{
  {
    .dev = { .ops = &g_spiio_ops },
    .base = PHYS_TO_UNCACHED(LS2K300_SPI2_BASE),
    .clock_freq = LS2K300_SPIIO_CLOCK_FREQ,
    .nbits = 8,
  },
  {
    .dev = { .ops = &g_spiio_ops },
    .base = PHYS_TO_UNCACHED(LS2K300_SPI3_BASE),
    .clock_freq = LS2K300_SPIIO_CLOCK_FREQ,
    .nbits = 8,
  },
};

FAR struct spi_dev_s *ls2k300_spiio_initialize(int port)
{
  FAR struct ls2k300_spiio_priv_s *priv;
  uint32_t cfg1;
  uint32_t cfg3;

  if (port < 0 || port > 1)
    return NULL;

  priv = &g_spiio_priv[port];

  if (!priv->initialized)
    {
      uint32_t sr1;
      int i;

      /* Bus reset — matches spi2_bus_reset() from working test code */

      cfg1 = spiio_read_reg(priv, LS2K300_SPIIO_CR1);
      cfg1 &= ~(CR1_CSTART | CR1_AUTOSUS);
      spiio_write_reg(priv, LS2K300_SPIIO_CR1, cfg1);

      spiio_write_reg(priv, LS2K300_SPIIO_CR4, 0);
      spiio_write_reg(priv, LS2K300_SPIIO_CR3, 0);
      up_udelay(10);

      /* Clear all W1C status flags */

      spiio_write_reg(priv, LS2K300_SPIIO_SR1,
                      SR1_EOT | 0x0f00);
      up_udelay(10);

      /* Drain RX FIFO */

      for (i = 0; i < 4; i++)
        {
          sr1 = spiio_read_reg(priv, LS2K300_SPIIO_SR1);
          if (sr1 & 0x10)
            break;

          (void)spiio_read_reg_byte(priv, LS2K300_SPIIO_DR);
        }

      /* Enable SPI */

      spiio_write_reg(priv, LS2K300_SPIIO_CR1, CR1_SPE);

      /* 8-bit frame */

      cfg1 = spiio_read_reg(priv, LS2K300_SPIIO_CFG1);
      cfg1 &= ~CFG1_DSIZE_MASK;
      cfg1 |= ((8 - 1) << CFG1_DSIZE_SHIFT);
      spiio_write_reg(priv, LS2K300_SPIIO_CFG1, cfg1);

      /* Master, full duplex, SSMODE=0 (auto-CS).
       * GPIO85 is locked to SPIIO2_CSN by pinmux (0x16000xxx region
       * reads always return 0xFFFFFFFF in kernel). Hardware auto-CS
       * asserts on CSTART, deasserts on EOT.
       * Multi-byte CS hold: select(true)→send()→send()→...→select(false).
       */

      cfg3 = spiio_read_reg(priv, LS2K300_SPIIO_CFG3);
      cfg3 |= CFG3_MSTR;
      cfg3 |= CFG3_DIE;
      cfg3 |= CFG3_DOE;
      cfg3 &= ~CFG3_SSMODE_MASK;
      /* SSMODE=0 */
      spiio_write_reg(priv, LS2K300_SPIIO_CFG3, cfg3);

      spiio_write_reg(priv, LS2K300_SPIIO_IER, 0);

      priv->initialized = true;
    }

  return &priv->dev;
}

