  {
    .dev = { .ops = &g_spiio_ops },
    .base = PHYS_TO_UNCACHED(LS2K300_SPI2_BASE),
    .clock_freq = SPIIO_CLOCK_FREQ,
    .nbits = 8,
  },
  {
    .dev = { .ops = &g_spiio_ops },
    .base = PHYS_TO_UNCACHED(LS2K300_SPI3_BASE),
    .clock_freq = SPIIO_CLOCK_FREQ,
    .nbits = 8,
  },
};

/* ===== initialize — matches spi2_init() ===== */

FAR struct spi_dev_s *ls2k300_spiio_initialize(int port)
{
  FAR struct ls2k300_spiio_priv_s *priv;
  uint32_t brint;

  if (port < 0 || port > 1)
    return NULL;

  priv = &g_spiio_priv[port];

  if (!priv->initialized)
    {
      /* 1. Enable clock gate (CFG5 bit 17/18, handled by bringup) */

      /* 2. SSMODE_SW, DIE, DOE, MSTR */

      spiio_write_reg(priv, LS2K300_SPIIO_CFG3,
                      CFG3_MSTR | CFG3_DIE | CFG3_DOE | (1U << 8));

      /* 3. 8-bit frame */

      spiio_write_reg(priv, LS2K300_SPIIO_CFG1,
                      (7U << CFG1_DSIZE_SHIFT));

      /* 4. Baud rate */

      brint = priv->clock_freq / (CONFIG_GD25_SPIFREQUENCY ?
                  CONFIG_GD25_SPIFREQUENCY : 10000000);
      if (brint < 2)
        brint = 2;
      if (brint > 255)
        brint = 255;

      spiio_write_reg(priv, LS2K300_SPIIO_CFG2,
                      brint << CFG2_BRINT_SHIFT);

      /* 5. Enable SPI */

      spiio_write_reg(priv, LS2K300_SPIIO_CR1, CR1_SPE);

      up_udelay(10);

      priv->initialized = true;
    }

  return &priv->dev;
}

