211	/* ===== send (single byte) — EXACT MATCH of spi2_xfer_byte() =====
212	 *
213	 * CS asserted BEFORE this function by select(true).
214	 * CS deasserted AFTER by select(false).
215	 */
216	
217	static uint32_t ls2k300_spiio_send(FAR struct spi_dev_s *dev, uint32_t wd)
218	{
219	  FAR struct ls2k300_spiio_priv_s *priv =
220	      (FAR struct ls2k300_spiio_priv_s *)dev;
221	  uint32_t val;
222	  uint32_t sr1;
223	  uint32_t i;
224	
225	  /* 1. Enable SPE */
226	
227	  val = spiio_read_reg(priv, LS2K300_SPIIO_CR1);
228	  val |= CR1_SPE;
229	  spiio_write_reg(priv, LS2K300_SPIIO_CR1, val);
230	
231	  /* 2. Clear CSTART/AUTOSUS for clean rising edge */
232	
233	  val = spiio_read_reg(priv, LS2K300_SPIIO_CR1);
234	  val &= ~(CR1_CSTART | CR1_AUTOSUS);
235	  spiio_write_reg(priv, LS2K300_SPIIO_CR1, val);
236	
237	  /* 3. Clear W1C status flags */
238	
239	  spiio_write_reg(priv, LS2K300_SPIIO_SR1, SR1_W1C_FLAGS);
240	
241	  /* 4. TSIZE = 0 (single frame) */
242	
243	  spiio_write_reg(priv, LS2K300_SPIIO_CR3, 0);
244	
245	  /* 5. Wait for TX FIFO available */
246	
247	  for (i = 0; i < SPIIO_TIMEOUT; i++)
248	    {
249	      sr1 = spiio_read_reg(priv, LS2K300_SPIIO_SR1);
250	      if (sr1 & SR1_TXA)
251	        break;
252	
253	      up_udelay(1);
254	    }
255	
256	  if (i >= SPIIO_TIMEOUT)
257	    {
258	      spiio_abort(priv);
259	      return 0;
260	    }
261	
262	  /* 6. Write TX byte (8-bit access!) */
263	
264	  spiio_write_reg_byte(priv, LS2K300_SPIIO_DR, (uint8_t)(wd & 0xff));
265	
266	  /* 7. CSTART only, no AUTOSUS */
267	
268	  val = spiio_read_reg(priv, LS2K300_SPIIO_CR1);
269	  val |= CR1_CSTART;
270	  spiio_write_reg(priv, LS2K300_SPIIO_CR1, val);
271	
272	  /* 8. Wait EOT */
273	
274	  for (i = 0; i < SPIIO_TIMEOUT; i++)
275	    {
276	      sr1 = spiio_read_reg(priv, LS2K300_SPIIO_SR1);
277	      if (sr1 & SR1_EOT)
278	        break;
279	
280	      up_udelay(1);
281	    }
282	
283	  if (i >= SPIIO_TIMEOUT)
284	    {
285	      spiio_abort(priv);
286	      return 0;
287	    }
288	
289	  /* 9. Clear EOT */
290	
291	  spiio_write_reg(priv, LS2K300_SPIIO_SR1, SR1_EOT);
292	
293	  /* 10. Wait RX FIFO */
294	
295	  for (i = 0; i < SPIIO_TIMEOUT; i++)
296	    {
297	      sr1 = spiio_read_reg(priv, LS2K300_SPIIO_SR1);
298	      if (sr1 & SR1_RXA)
299	        break;
300	
301	      up_udelay(1);
302	    }
303	
304	  if (i >= SPIIO_TIMEOUT)
305	    {
306	      spiio_abort(priv);
307	      return 0;
308	    }
309	
310	  /* 11. Read RX byte (8-bit access!) */
311	
312	  return (uint32_t)spiio_read_reg_byte(priv, LS2K300_SPIIO_DR);
313	}
