478	FAR struct spi_dev_s *ls2k300_spiio_initialize(int port)
479	{
480	  FAR struct ls2k300_spiio_priv_s *priv;
481	  uint32_t brint;
482	
483	  if (port < 0 || port > 1)
484	    return NULL;
485	
486	  priv = &g_spiio_priv[port];
487	
488	  if (!priv->initialized)
489	    {
490	      /* 1. Enable clock gate (CFG5 bit 17/18, handled by bringup) */
491	
492	      /* 2. SSMODE_SW, DIE, DOE, MSTR */
493	
494	      spiio_write_reg(priv, LS2K300_SPIIO_CFG3,
495	                      CFG3_MSTR | CFG3_DIE | CFG3_DOE | (1U << 8));
496	
497	      /* 3. 8-bit frame */
498	
499	      spiio_write_reg(priv, LS2K300_SPIIO_CFG1,
500	                      (7U << CFG1_DSIZE_SHIFT));
501	
502	      /* 4. Baud rate */
503	
504	      brint = priv->clock_freq / (CONFIG_GD25_SPIFREQUENCY ?
505	                  CONFIG_GD25_SPIFREQUENCY : 10000000);
506	      if (brint < 2)
507	        brint = 2;
508	      if (brint > 255)
509	        brint = 255;
510	
511	      spiio_write_reg(priv, LS2K300_SPIIO_CFG2,
512	                      brint << CFG2_BRINT_SHIFT);
513	
514	      /* 5. Enable SPI */
515	
516	      spiio_write_reg(priv, LS2K300_SPIIO_CR1, CR1_SPE);
517	
518	      up_udelay(10);
519	
520	      priv->initialized = true;
521	    }
522	
523	  return &priv->dev;
524	}
