149	/****************************************************************************
150	 * Name: mount_sprintf
151	 *
152	 * Description:
153	 *   Generate otuput from fs/mount, fs/blocks, or fs/usage, file read.
154	 *
155	 ****************************************************************************/
156	
157	static void mount_sprintf(FAR struct mount_info_s *info,
158	                          FAR const char *fmt, ...)
159	{
160	  size_t linesize;
161	  size_t copysize;
162	  va_list ap;
163	
164	  /* Print the format and data to a line buffer */
165	
166	  va_start(ap, fmt);
167	  linesize = vsnprintf(info->line, info->linelen, fmt, ap);
168	  va_end(ap);
169	
170	  /* Copy the line buffer to the user buffer */
171	
172	  copysize = procfs_memcpy(info->line, linesize,
173	                           info->buffer, info->remaining,
174	                           &info->offset);
175	
176	  /* Update counts and pointers */
177	
178	  info->totalsize += copysize;
179	  info->buffer    += copysize;
180	  info->remaining -= copysize;
181	}
