193	
194	#ifndef CONFIG_FS_PROCFS_EXCLUDE_MOUNT
195	static int mount_entry(FAR const char *mountpoint,
196	                       FAR struct statfs *statbuf, FAR void *arg)
197	{
198	  FAR struct mount_info_s *info = (FAR struct mount_info_s *)arg;
199	  FAR const char *fstype;
200	
201	  DEBUGASSERT(mountpoint != NULL && statbuf != NULL && info != NULL);
202	
203	  /* Get the file system type */
204	
205	  fstype = fs_gettype(statbuf);
206	
207	  /* Generate mount list one line at a time */
208	
209	  mount_sprintf(info, "  %s type %s\n", mountpoint, fstype);
210	  return (info->totalsize >= info->buflen) ? 1 : 0;
211	}
212	#endif
