214	/****************************************************************************
215	 * Name: blocks_entry
216	 *
217	 * Description:
218	 *   Output one fs/blocks entry
219	 *
220	 *   Format:
221	 *     <mountpoint> type <type>
222	 *
223	 ****************************************************************************/
224	
225	#ifndef CONFIG_FS_PROCFS_EXCLUDE_BLOCKS
226	static int blocks_entry(FAR const char *mountpoint,
227	                        FAR struct statfs *statbuf, FAR void *arg)
228	{
229	  FAR struct mount_info_s *info = (FAR struct mount_info_s *)arg;
230	
231	  DEBUGASSERT(mountpoint != NULL && statbuf != NULL && info != NULL);
232	
233	  /* Have we generated the header yet? */
234	
235	  if (!info->header)
236	    {
237	      mount_sprintf(info,
238	                    "  Block    Number\n");
239	      mount_sprintf(info,
240	                    "  Size     Blocks       Used   Available Mounted on\n");
241	      info->header = true;
242	    }
243	
244	  /* Generate blocks list one line at a time */
245	
246	  mount_sprintf(info, "%6zu %10" PRIuOFF " %10" PRIuOFF
247	                "  %10" PRIuOFF " %s\n",
248	                statbuf->f_bsize, statbuf->f_blocks,
249	                statbuf->f_blocks - statbuf->f_bavail, statbuf->f_bavail,
250	                mountpoint);
251	
252	  return (info->totalsize >= info->buflen) ? 1 : 0;
253	}
254	#endif
255	
256	/****************************************************************************
257	 * Name: blocks_entry
258	 *
259	 * Description:
260	 *   Output one fs/usage entry
261	 *
262	 *   Format:
263	 *     <mountpoint> type <type>
264	 *
265	 ****************************************************************************/
266	
267	#ifndef CONFIG_FS_PROCFS_EXCLUDE_USAGE
268	static int usage_entry(FAR const char *mountpoint,
269	                       FAR struct statfs *statbuf, FAR void *arg)
270	{
271	  FAR struct mount_info_s *info = (FAR struct mount_info_s *)arg;
272	  FAR const char *fstype;
273	  fsblkcnt_t size;
274	  fsblkcnt_t used;
275	  fsblkcnt_t free;
276	  int which;
277	  char sizelabel;
278	  char freelabel;
279	  char usedlabel;
280	  static const char labels[5] =
281	  {
282	    'B', 'K', 'M', 'G', 'T'
283	  };
284	
285	  DEBUGASSERT(mountpoint != NULL && statbuf != NULL && info != NULL);
286	
287	  /* Have we generated the header yet? */
288	
289	  if (!info->header)
290	    {
291	      mount_sprintf(info,
292	        "  Filesystem      Size      Used  Available Mounted on\n");
293	      info->header = true;
294	    }
295	
296	  /* Get the file system type */
297	
298	  fstype = fs_gettype(statbuf);
299	
300	  size = statbuf->f_bsize * statbuf->f_blocks;
301	  free = statbuf->f_bsize * statbuf->f_bavail;
302	  used = size - free;
303	
304	  /* Find the label for size */
305	
306	  which = 0;
307	  while (size >= 9999 || ((size & 0x3ff) == 0 && size != 0))
308	    {
309	      which++;
310	      size >>= 10;
311	    }
312	
313	  sizelabel = labels[which];
314	
315	  /* Find the label for free */
316	
317	  which = 0;
318	  while (free >= 9999 || ((free & 0x3ff) == 0 && free != 0))
319	    {
320	      which++;
321	      free >>= 10;
322	    }
323	
324	  freelabel = labels[which];
325	
326	  /* Find the label for used */
327	
328	  which = 0;
329	  while (used >= 9999 || ((used & 0x3ff) == 0 && used != 0))
330	    {
331	      which++;
332	      used >>= 10;
333	    }
334	
335	  usedlabel = labels[which];
336	
337	  /* Generate usage list one line at a time */
338	
339	  mount_sprintf(info,
340	    "  %-10s %8" PRIuOFF "%c %8" PRIuOFF "%c  %8" PRIuOFF "%c %s\n",
341	    fstype, size, sizelabel, used, usedlabel, free, freelabel, mountpoint);
342	
343	  return (info->totalsize >= info->buflen) ? 1 : 0;
344	}
345	#endif
