347	/****************************************************************************
348	 * Name: mount_open
349	 ****************************************************************************/
350	
351	static int mount_open(FAR struct file *filep, FAR const char *relpath,
352	                      int oflags, mode_t mode)
353	{
354	  FAR struct mount_file_s *procfile;
355	  uint8_t id;
356	
357	  finfo("Open '%s'\n", relpath);
358	
359	  /* PROCFS is read-only.  Any attempt to open with any kind of write
360	   * access is not permitted.
361	   *
362	   * REVISIT:  Write-able proc files could be quite useful.
363	   */
364	
365	  if ((oflags & O_WRONLY) != 0 || (oflags & O_RDONLY) == 0)
366	    {
367	      ferr("ERROR: Only O_RDONLY supported\n");
368	      return -EACCES;
369	    }
370	
371	  /* "fs/mount", "fs/block", and "fs/usage" are the only acceptable values
372	   * for the relpath.
373	   */
374	
375	#ifndef CONFIG_FS_PROCFS_EXCLUDE_MOUNT
376	  if (strcmp(relpath, "fs/mount") == 0)
377	    {
378	      id = FS_MOUNT_FILE;
379	    }
380	#endif
381	#ifndef CONFIG_FS_PROCFS_EXCLUDE_BLOCKS
382	  else if (strcmp(relpath, "fs/blocks") == 0)
383	    {
384	      id = FS_BLOCKS_FILE;
385	    }
386	#endif
387	  else if (strcmp(relpath, "fs/usage") == 0)
388	    {
389	      id = FS_USAGE_FILE;
390	    }
391	  else
392	    {
393	      ferr("ERROR: relpath is '%s'\n", relpath);
394	      return -ENOENT;
395	    }
396	
397	  /* Allocate a container to hold the task and node selection */
398	
399	  procfile = (FAR struct mount_file_s *)
400	    fs_heap_zalloc(sizeof(struct mount_file_s));
401	  if (!procfile)
402	    {
403	      ferr("ERROR: Failed to allocate file container\n");
404	      return -ENOMEM;
405	    }
406	
407	  /* Save the file ID */
408	
409	  procfile->id = id;
410	
411	  /* Save the open-specific state in filep->f_priv */
412	
413	  filep->f_priv = (FAR void *)procfile;
414	  return OK;
415	}
