437	/****************************************************************************
438	 * Name: mount_read
439	 ****************************************************************************/
440	
441	static ssize_t mount_read(FAR struct file *filep, FAR char *buffer,
442	                          size_t buflen)
443	{
444	  FAR struct mount_file_s *procfile;
445	  struct mount_info_s info;
446	  foreach_mountpoint_t handler;
447	  ssize_t ret;
448	
449	  finfo("buffer=%p buflen=%d\n", buffer, (int)buflen);
450	
451	  /* Recover our private data from the struct file instance */
452	
453	  procfile = (FAR struct mount_file_s *)filep->f_priv;
454	  DEBUGASSERT(procfile);
455	
456	  /* Provide the requested data */
457	
458	  memset(&info, 0, sizeof(struct mount_info_s));
459	  info.line      = procfile->line;
460	  info.buffer    = buffer;
461	  info.linelen   = MOUNT_LINELEN;
462	  info.buflen    = buflen;
463	  info.remaining = buflen;
464	  info.offset    = filep->f_pos;
465	  info.header    = false;
466	
467	  switch (procfile->id)
468	    {
469	#ifndef CONFIG_FS_PROCFS_EXCLUDE_MOUNT
470	      case FS_MOUNT_FILE:                 /* /proc/fs/mount */
471	        handler = mount_entry;
472	        break;
473	#endif
474	
475	#ifndef CONFIG_FS_PROCFS_EXCLUDE_BLOCKS
476	      case FS_BLOCKS_FILE:                /* /proc/fs/blocks */
477	        handler = blocks_entry;
478	        break;
479	#endif
480	
481	#ifndef CONFIG_FS_PROCFS_EXCLUDE_USAGE
482	      case FS_USAGE_FILE:                 /* /proc/fs/usage */
483	        handler = usage_entry;
484	        break;
485	#endif
486	
487	      default:
488	        DEBUGPANIC();
489	        return -EINVAL;
490	    }
491	
492	  /* Generate each entry in the routing table */
493	
494	  foreach_mountpoint(handler, &info);
495	  ret = info.totalsize;
496	
497	  /* Update the file offset */
498	
499	  if (ret > 0)
500	    {
501	      filep->f_pos += ret;
502	    }
503	
504	  return ret;
505	}
506	
507	#endif /* !CONFIG_FS_PROCFS_EXCLUDE_MOUNT || \
508	        * !CONFIG_FS_PROCFS_EXCLUDE_BLOCKS || \
509	        * !CONFIG_FS_PROCFS_EXCLUDE_USAGE */
510	#endif /* !CONFIG_DISABLE_MOUNTPOINT && CONFIG_FS_PROCFS */
