1537	
1538	static int littlefs_statfs(FAR struct inode *mountpt, FAR struct statfs *buf)
1539	{
1540	  FAR struct littlefs_mountpt_s *fs;
1541	  int ret;
1542	
1543	  /* Get the mountpoint private data from the inode structure */
1544	
1545	  fs = mountpt->i_private;
1546	
1547	  /* Return something for the file system description */
1548	
1549	  buf->f_type    = LITTLEFS_SUPER_MAGIC;
1550	  buf->f_namelen = LFS_NAME_MAX;
1551	  buf->f_bsize   = fs->cfg.block_size;
1552	  buf->f_blocks  = fs->cfg.block_count;
1553	  buf->f_bfree   = fs->cfg.block_count;
1554	  buf->f_bavail  = fs->cfg.block_count;
1555	
1556	  ret = nxmutex_lock(&fs->lock);
1557	  if (ret < 0)
1558	    {
1559	      return ret;
1560	    }
1561	
1562	  ret = littlefs_convert_result(lfs_fs_size(&fs->lfs));
1563	  if (ret > 0)
1564	    {
1565	      buf->f_bfree -= ret;
1566	      buf->f_bavail -= ret;
1567	
1568	      ret = 0;
1569	    }
1570	
1571	  nxmutex_unlock(&fs->lock);
1572	  return ret;
1573	}
