94	size_t procfs_memcpy(FAR const char *src, size_t srclen,
95	                     FAR char *dest, size_t destlen,
96	                     FAR off_t *offset)
97	{
98	  size_t copysize;
99	  size_t lnoffset;
100	
101	  /* Will this line take us past the offset? */
102	
103	  lnoffset = *offset;
104	  if (srclen < lnoffset)
105	    {
106	      /* No... decrement the offset and return without doing anything */
107	
108	      *offset -= srclen;
109	      return 0;
110	    }
111	
112	  /* Handle the remaining offset */
113	
114	  srclen -= lnoffset;
115	  src    += lnoffset;
116	  *offset = 0;
117	
118	  /* Copy the line into the user destination buffer */
119	
120	  copysize = MIN(srclen, destlen);
121	  memcpy(dest, src, copysize);
122	  return copysize;
123	}
