446	
447	FAR struct spi_dev_s *ls2k300_spiio_initialize(int port)
448	{
449	  FAR struct ls2k300_spiio_priv_s *priv;
450	  uint32_t brint;
451	
452	  if (port < 0 || port > 1)
453	    return NULL;
454	
455	  priv = &g_spiio_priv[port];
456	
457	  if (!priv->initialized)
458	    {
459	      /* 1. Enable clock gate (CFG5 bit 17/18, handled by bringup) */
460	
461	      /* 2. SSMODE_SW, DIE, DOE, MSTR */
462	
463	      spiio_write_reg(priv, LS2K300_SPIIO_CFG3,
464	                      CFG3_MSTR | CFG3_DIE | CFG3_DOE | (1U << 8));
465	
466	      /* 3. 8-bit frame */
467	
468	      spiio_write_reg(priv, LS2K300_SPIIO_CFG1,
469	                      (7U << CFG1_DSIZE_SHIFT));

470	
471	      /* 4. Baud rate */
472	
473	      brint = priv->clock_freq / (CONFIG_GD25_SPIFREQUENCY ?
474	                  CONFIG_GD25_SPIFREQUENCY : 10000000);
475	      if (brint < 2)
476	        brint = 2;
477	      if (brint > 255)
478	        brint = 255;
479	
480	      spiio_write_reg(priv, LS2K300_SPIIO_CFG2,
481	                      brint << CFG2_BRINT_SHIFT);
482	
483	      /* 5. Enable SPI */
484	
485	      spiio_write_reg(priv, LS2K300_SPIIO_CR1, CR1_SPE);
486	
487	      up_udelay(10);
488	
489	      priv->initialized = true;
490	    }
491	
